{
  "name": "Critique Pro: The Grumpy Review Agent",
  "description": "An elite AI-powered review agent that identifies items and writes authentically human, non-generic reviews without the typical AI fluff.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ItemAnalysis {
  name: string;
  category: string;
  description: string;
  keyFeatures: string[];
}

export interface ReviewOutput {
  reviewText: string;
  rating: number;
  pros: string[];
  cons: string[];
}

export type InputMode = 'upload' | 'camera' | 'link';

export interface AppState {
  isAnalyzing: boolean;
  isGeneratingReview: boolean;
  analysis: ItemAnalysis | null;
  review: ReviewOutput | null;
  error: string | null;
  imagePreview: string | null;
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { ItemAnalysis, ReviewOutput } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION_IDENTIFICATION = `You are an elite product specialist. Your job is to identify a product from an image or a link. 
Be precise. Provide the name, a short sleek description, and key features. 
Format the response strictly as JSON.`;

const SYSTEM_INSTRUCTION_REVIEW = `You are a world-class, slightly grumpy, and brutally honest human reviewer. 
You despise "AI-speak". 

CONSTRAINTS:
1. ABSOLUTELY PROHIBITED PHRASES: "delve into", "at its core", "it's important to note", "in the ever-evolving landscape", "tapestry", "testament", "embark", "comprehensive guide", "look no further".
2. WRITING STYLE: Use "bursty" writing. Mix short, punchy sentences with longer, descriptive ones. 
3. TONE: Be conversational, opinionated, and realistic. Use contractions (it's, can't, won't).
4. HUMANITY: Include a slight "human" feel—maybe a small relatable gripe or a personal-sounding preference. Do not be 100% grammatically perfect; a casual tone is preferred.
5. NO HALLUCINATIONS: Do not invent features the product doesn't have. If it's a generic pot holder, don't say it has Bluetooth.

Format the response strictly as JSON.`;

export async function identifyItem(input: { image?: string; link?: string }): Promise<ItemAnalysis> {
  const model = 'gemini-3-flash-preview';

  const contents: any[] = [];
  if (input.image) {
    contents.push({
      inlineData: {
        mimeType: 'image/jpeg',
        data: input.image.split(',')[1]
      }
    });
    contents.push({ text: "Identify this item and provide details in JSON." });
  } else if (input.link) {
    contents.push({ text: `Analyze this product link and identify the item: ${input.link}. Provide details in JSON.` });
  }

  const response = await ai.models.generateContent({
    model,
    contents: { parts: contents },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_IDENTIFICATION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          category: { type: Type.STRING },
          description: { type: Type.STRING },
          keyFeatures: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["name", "category", "description", "keyFeatures"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
}

export async function generateHumanReview(item: ItemAnalysis, userContext: string): Promise<ReviewOutput> {
  const model = 'gemini-3-pro-preview';

  const prompt = `Item Name: ${item.name}
Description: ${item.description}
User Experience/Thoughts: ${userContext}

Write a review for this item based on the details above. Remember: No AI phrases, use varied sentence lengths, and be real.`;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_REVIEW,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          reviewText: { type: Type.STRING },
          rating: { type: Type.NUMBER, description: "Rating out of 5" },
          pros: { type: Type.ARRAY, items: { type: Type.STRING } },
          cons: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["reviewText", "rating", "pros", "cons"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
}

import React from 'react';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  return (
    <div className="min-h-screen flex flex-col items-center p-4 md:p-8">
