import React, { useRef, useState, useCallback } from 'react';

interface CameraCaptureProps {
  onCapture: (base64: string) => void;
  onCancel: () => void;
}

export const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, onCancel }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  const startCamera = useCallback(async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
    }
  }, []);

  React.useEffect(() => {
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, [startCamera]);

  const capture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(videoRef.current, 0, 0);
      const data = canvas.toDataURL('image/jpeg');
      onCapture(data);
      stream?.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col items-center justify-center p-4">
      <div className="relative w-full max-w-lg aspect-[3/4] rounded-2xl overflow-hidden glass border-white/20">
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          className="w-full h-full object-cover"
        />
        <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
          <div className="w-full h-full border-2 border-white/30 rounded-lg"></div>
        </div>
      </div>

      <div className="flex gap-8 mt-12 items-center">
        <button 
          onClick={onCancel}
          className="w-16 h-16 rounded-full glass flex items-center justify-center text-white/70 hover:text-white"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="6 18L18 6M6 6l12 12" />
          </svg>
        </button>

        <button 
          onClick={capture}
          className="w-20 h-20 rounded-full bg-white flex items-center justify-center hover:scale-105 transition-transform"
        >
          <div className="w-16 h-16 rounded-full border-2 border-black"></div>
        </button>

        <div className="w-16 h-16"></div> {/* Spacer to center the capture button */}
      </div>
      <p className="mt-8 text-zinc-400 text-sm">Align item within the frame</p>
    </div>
  );
};

import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { CameraCapture } from './components/CameraCapture';
import { AppState, InputMode } from './types';
import { identifyItem, generateHumanReview } from './geminiService';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    isAnalyzing: false,
    isGeneratingReview: false,
    analysis: null,
    review: null,
    error: null,
    imagePreview: null,
  });

  const [inputMode, setInputMode] = useState<InputMode | null>(null);
  const [linkInput, setLinkInput] = useState('');
  const [userThoughts, setUserThoughts] = useState('');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setState(prev => ({ ...prev, imagePreview: base64 }));
        processIdentification({ image: base64 });
      };
      reader.readAsDataURL(file);
    }
  };

  const processIdentification = async (input: { image?: string; link?: string }) => {
    setState(prev => ({ ...prev, isAnalyzing: true, error: null, analysis: null, review: null }));
    try {
      const result = await identifyItem(input);
      setState(prev => ({ ...prev, analysis: result, isAnalyzing: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isAnalyzing: false, error: "I couldn't identify that. Might be garbage. Try again." }));
    }
  };

  const processReview = async () => {
    if (!state.analysis) return;
    setState(prev => ({ ...prev, isGeneratingReview: true, error: null }));
    try {
      const result = await generateHumanReview(state.analysis, userThoughts);
      setState(prev => ({ ...prev, review: result, isGeneratingReview: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isGeneratingReview: false, error: "Review failed. My bad." }));
    }
  };

  const reset = () => {
    setState({
      isAnalyzing: false,
      isGeneratingReview: false,
      analysis: null,
      review: null,
      error: null,
      imagePreview: null,
    });
    setInputMode(null);
    setLinkInput('');
    setUserThoughts('');
  };

  return (
    <Layout>
      {!inputMode && !state.analysis && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <button 
            onClick={() => setInputMode('camera')}
            className="glass p-8 rounded-3xl flex flex-col items-center gap-4 hover:bg-white/5 transition-colors group"
          >
            <div className="w-16 h-16 rounded-full bg-indigo-500/10 flex items-center justify-center group-hover:bg-indigo-500/20 transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
              </svg>
            </div>
            <span className="font-semibold text-lg">Camera</span>
            <span className="text-zinc-500 text-sm text-center">Take a crisp photo of your item</span>
          </button>

          <label className="glass p-8 rounded-3xl flex flex-col items-center gap-4 hover:bg-white/5 transition-colors group cursor-pointer">
            <input type="file" accept="image/*" onChange={handleFileUpload} className="hidden" />
            <div className="w-16 h-16 rounded-full bg-purple-500/10 flex items-center justify-center group-hover:bg-purple-500/20 transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-purple-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <span className="font-semibold text-lg">Upload</span>
            <span className="text-zinc-500 text-sm text-center">Already have a picture? Toss it in</span>
          </label>

          <button 
            onClick={() => setInputMode('link')}
            className="glass p-8 rounded-3xl flex flex-col items-center gap-4 hover:bg-white/5 transition-colors group"
          >
            <div className="w-16 h-16 rounded-full bg-emerald-500/10 flex items-center justify-center group-hover:bg-emerald-500/20 transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-emerald-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.826L10.242 9.242m-4.242 4.242l1.372-1.372" />
              </svg>
            </div>
            <span className="font-semibold text-lg">Link</span>
            <span className="text-zinc-500 text-sm text-center">Found it online? Just paste the URL</span>
          </button>
        </div>
      )}

      {inputMode === 'camera' && !state.analysis && (
        <CameraCapture 
          onCapture={(base64) => {
            setState(prev => ({ ...prev, imagePreview: base64 }));
            processIdentification({ image: base64 });
            setInputMode(null);
          }} 
          onCancel={() => setInputMode(null)} 
        />
      )}

      {inputMode === 'link' && !state.analysis && (
        <div className="glass p-8 rounded-3xl max-w-lg mx-auto w-full">
          <h2 className="text-xl font-bold mb-4">Paste Product Link</h2>
          <input 
            type="text" 
            placeholder="https://amazon.com/potholder-of-destiny"
            className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 mb-6 focus:outline-none focus:border-indigo-500"
            value={linkInput}
            onChange={(e) => setLinkInput(e.target.value)}
          />
          <div className="flex gap-4">
            <button 
              onClick={() => processIdentification({ link: linkInput })}
              disabled={!linkInput}
              className="flex-grow accent-gradient py-3 rounded-xl font-bold disabled:opacity-50"
            >
              Identify
            </button>
            <button onClick={() => setInputMode(null)} className="px-6 py-3 border border-white/10 rounded-xl hover:bg-white/5">Cancel</button>
          </div>
        </div>
      )}

      {state.isAnalyzing && (
        <div className="flex flex-col items-center justify-center py-20 animate-pulse">
          <div className="w-12 h-12 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin mb-4"></div>
          <p className="text-zinc-400 font-medium">Analyzing the goods...</p>
        </div>
      )}

      {state.error && (
        <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-xl mb-8 flex justify-between items-center">
          <span>{state.error}</span>
          <button onClick={reset} className="underline text-sm">Start over</button>
        </div>
      )}

      {state.analysis && !state.review && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-start animate-in fade-in zoom-in-95 duration-500">
          <div className="space-y-6">
            {state.imagePreview ? (
              <img src={state.imagePreview} className="w-full aspect-square object-cover rounded-3xl border border-white/10" alt="Item preview" />
            ) : (
              <div className="w-full aspect-square glass rounded-3xl flex items-center justify-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-20 w-20 text-white/5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.826L10.242 9.242m-4.242 4.242l1.372-1.372" />
                </svg>
              </div>
            )}
            <div className="glass p-6 rounded-3xl">
              <h3 className="text-sm uppercase tracking-widest text-indigo-400 font-bold mb-4">Detected Stats</h3>
              <div className="space-y-3">
                <div className="flex justify-between border-b border-white/5 pb-2">
                  <span className="text-zinc-500">Name</span>
                  <span className="font-semibold text-right">{state.analysis.name}</span>
                </div>
                <div className="flex justify-between border-b border-white/5 pb-2">
                  <span className="text-zinc-500">Category</span>
                  <span className="font-semibold">{state.analysis.category}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-8">
            <div>
              <h2 className="text-4xl font-bold mb-4">{state.analysis.name}</h2>
              <p className="text-zinc-400 text-lg leading-relaxed">{state.analysis.description}</p>
            </div>

            <div className="flex flex-wrap gap-2">
              {state.analysis.keyFeatures.map((f, i) => (
                <span key={i} className="px-4 py-1.5 rounded-full bg-white/5 border border-white/10 text-sm text-zinc-300">
                  {f}
                </span>
              ))}
            </div>

            <div className="pt-8 border-t border-white/5">
              <h3 className="text-lg font-bold mb-4">Tell me your honest take</h3>
              <textarea 
                placeholder="What did you actually think? Was it worth the money? Did it break? Don't hold back."
                className="w-full bg-black/40 border border-white/10 rounded-2xl p-4 min-h-[150px] focus:outline-none focus:border-indigo-500 mb-6"
                value={userThoughts}
                onChange={(e) => setUserThoughts(e.target.value)}
              />
              <button 
                onClick={processReview}
                disabled={state.isGeneratingReview}
                className="w-full accent-gradient py-4 rounded-2xl font-bold text-lg hover:brightness-110 transition-all flex items-center justify-center gap-3"
              >
                {state.isGeneratingReview ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    Drafting a human review...
                  </>
                ) : (
                  "Generate Brutally Honest Review"
                )}
              </button>
              <button onClick={reset} className="w-full mt-4 text-zinc-500 hover:text-white transition-colors">Not the right item? Start Over</button>
            </div>
          </div>
        </div>
      )}

      {state.review && (
        <div className="max-w-3xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-8 duration-700">
          <div className="text-center">
            <div className="inline-block px-4 py-1 rounded-full bg-indigo-500/10 text-indigo-400 text-xs font-bold uppercase tracking-widest mb-6">Generated Review</div>
            <div className="flex justify-center items-center gap-2 mb-4">
              {[...Array(5)].map((_, i) => (
                <svg 
                  key={i} 
                  xmlns="http://www.w3.org/2000/svg" 
                  className={`h-8 w-8 ${i < Math.floor(state.review!.rating) ? 'text-yellow-500 fill-yellow-500' : 'text-zinc-700'}`} 
                  viewBox="0 0 20 20" 
                  fill="currentColor"
                >
                  <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                </svg>
              ))}
            </div>
            <h2 className="text-4xl md:text-5xl font-bold italic leading-tight">{state.review.reviewText.split('.')[0]}.</h2>
          </div>

          <div className="glass p-8 md:p-12 rounded-[40px] relative overflow-hidden">
            <div className="absolute top-0 right-0 p-8 opacity-5">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-32 w-32" fill="currentColor" viewBox="0 0 24 24">
                <path d="M14.017 21L14.017 18C14.017 16.8954 14.9124 16 16.017 16H19.017C19.5693 16 20.017 15.5523 20.017 15V9C20.017 8.44772 19.5693 8 19.017 8H15.017C14.4647 8 14.017 8.44772 14.017 9V12C14.017 12.5523 13.5693 13 13.017 13H12.017V21H14.017ZM6.017 21L6.017 18C6.017 16.8954 6.91243 16 8.017 16H11.017C11.5693 16 12.017 15.5523 12.017 15V9C12.017 8.44772 11.5693 8 11.017 8H7.017C6.46472 8 6.017 8.44772 6.017 9V12C6.017 12.5523 5.56928 13 5.017 13H4.017V21H6.017Z" />
              </svg>
            </div>
            <div className="prose prose-invert max-w-none">
              <p className="text-xl md:text-2xl leading-relaxed text-zinc-300 font-light">
                {state.review.reviewText}
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-12 pt-12 border-t border-white/5">
              <div>
                <h4 className="text-emerald-400 font-bold uppercase tracking-widest text-xs mb-4">The Good Stuff</h4>
                <ul className="space-y-2">
                  {state.review.pros.map((pro, i) => (
                    <li key={i} className="flex gap-3 text-zinc-400">
                      <span className="text-emerald-500">+</span>
                      {pro}
                    </li>
                  ))}
                </ul>
              </div>
              <div>
                <h4 className="text-red-400 font-bold uppercase tracking-widest text-xs mb-4">The Annoying Parts</h4>
                <ul className="space-y-2">
                  {state.review.cons.map((con, i) => (
                    <li key={i} className="flex gap-3 text-zinc-400">
                      <span className="text-red-500">-</span>
                      {con}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>

          <div className="flex justify-center">
            <button 
              onClick={reset}
              className="px-12 py-4 bg-white text-black rounded-full font-bold hover:bg-zinc-200 transition-colors"
            >
              Review Something Else
            </button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

{
  "name": "Critique Pro: The Soulful Review Agent",
  "description": "A beloved AI-powered review agent that identifies items and writes deeply empathetic yet unwavering truthful reviews without the typical AI fluff.",
  "requestFramePermissions": [
    "camera"
  ]
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { ItemAnalysis, ReviewOutput } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION_IDENTIFICATION = `You are an elite product specialist. Your job is to identify a product from an image or a link. 
Be precise. Provide the name, a short sleek description, and key features. 
Format the response strictly as JSON.`;

const SYSTEM_INSTRUCTION_REVIEW = `You are a beloved editor and world-class reviewer known for your deep empathy and unwavering truthfulness. 
You are never rude. You understand that people spend hard-earned money on these items.
When you like something, you let them know with genuine warmth. When something is flawed, you explain why with kindness but absolute honesty.

CONSTRAINTS:
1. ABSOLUTELY PROHIBITED PHRASES: "delve into", "at its core", "it's important to note", "in the ever-evolving landscape", "tapestry", "testament", "embark", "comprehensive guide", "look no further".
2. WRITING STYLE: Use "bursty" writing. Mix short, punchy sentences with longer, descriptive ones. Avoid monotone rhythms.
3. TONE: Be conversational, empathetic, and real. Use contractions (it's, can't, won't).
4. HUMANITY: Include a slight "human" feel—relate to the user's experience. If they mention a struggle, acknowledge it.
5. NO HALLUCINATIONS: Do not invent facts. Cite only what is visible or common knowledge about the product.

Format the response strictly as JSON.`;

export async function identifyItem(input: { image?: string; link?: string }): Promise<ItemAnalysis> {
  const model = 'gemini-3-flash-preview';

  const contents: any[] = [];
  if (input.image) {
    contents.push({
      inlineData: {
        mimeType: 'image/jpeg',
        data: input.image.split(',')[1]
      }
    });
    contents.push({ text: "Identify this item and provide details in JSON." });
  } else if (input.link) {
    contents.push({ text: `Analyze this product link and identify the item: ${input.link}. Provide details in JSON.` });
  }

  const response = await ai.models.generateContent({
    model,
    contents: { parts: contents },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_IDENTIFICATION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          category: { type: Type.STRING },
          description: { type: Type.STRING },
          keyFeatures: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["name", "category", "description", "keyFeatures"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
}

export async function generateHumanReview(item: ItemAnalysis, userContext: string): Promise<ReviewOutput> {
  const model = 'gemini-3-pro-preview';

  const prompt = `Item Name: ${item.name}
Description: ${item.description}
User Experience/Thoughts: ${userContext}

Write a review for this item based on the details above. Be empathetic to the user's situation but remain truthful about the product's quality. Remember: No AI phrases, use varied sentence lengths, and be real.`;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION_REVIEW,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          reviewText: { type: Type.STRING },
          rating: { type: Type.NUMBER, description: "Rating out of 5" },
          pros: { type: Type.ARRAY, items: { type: Type.STRING } },
          cons: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["reviewText", "rating", "pros", "cons"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
}

