  const [linkInput, setLinkInput] = useState('');
  const [userThoughts, setUserThoughts] = useState('');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setState(prev => ({ ...prev, imagePreview: base64 }));
        processIdentification({ image: base64 });
      };
      reader.readAsDataURL(file);
    }
  };

  const processIdentification = async (input: { image?: string; link?: string }) => {
    setState(prev => ({ ...prev, isAnalyzing: true, error: null, analysis: null, review: null }));
    try {
      const result = await identifyItem(input);
      setState(prev => ({ ...prev, analysis: result, isAnalyzing: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isAnalyzing: false, error: "I couldn't quite identify that. Could you try a different angle?" }));
    }
  };

  const processReview = async () => {
    if (!state.analysis) return;
    setState(prev => ({ ...prev, isGeneratingReview: true, error: null }));
    try {
      const result = await generateHumanReview(state.analysis, userThoughts);
      setState(prev => ({ ...prev, review: result, isGeneratingReview: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isGeneratingReview: false, error: "Something went wrong while writing the review. Let's try once more." }));
